#include "edward/ai/ai_orchestrator.hpp"
#include <QJsonDocument>
namespace edward::ai { AiResult AiOrchestrator::handle(const QString& output, const ProjectSnapshot& project) const { QJsonParseError parseError; const auto document = QJsonDocument::fromJson(output.toUtf8(), &parseError); if (!document.isObject()) return {AiResult::Kind::Conversation, output.trimmed(), {}}; QString error; const auto plan = ActionPlan::parse(document.object(), &error); if (!plan) { if (document.object().contains("react") || document.object().contains("css") || document.object().contains("componentIr") || document.object().contains("root")) return {AiResult::Kind::Unsupported, QStringLiteral("此组件载荷不符合 Edward 原生运行时协议。"), {}}; return {AiResult::Kind::Clarification, QStringLiteral("无法确认该项目修改，请明确目标、资源或位置。"), {}}; } if (!plan->validate(project, &error)) return {AiResult::Kind::Clarification, error, {}}; return {AiResult::Kind::ActionPlan, {}, plan}; } }
